local root=assert(os.getenv('QCOM_VP_PROBE_ROOT'))..'/'
platform={moduletype='Container',
    qemu_inst_mgr={moduletype='QemuInstanceManager'},
    apss_instance={moduletype='QemuInstance',args={'&qemu_inst_mgr','AARCH64'},accel='tcg',
        sync_policy='multithread-quantum'},
    apss_router={moduletype='router'},
    apss_access={moduletype='AccessMonitor',
        initiator_socket={bind='&apss_router.target_socket'}},
    apss={moduletype='cpu_arm_cortexA53',args={'&apss_instance'},rvbar=0x300000,
        has_el3=true,has_el2=true,mem={bind='&apss_access.target_socket'}},
    rom={moduletype='gs_memory',read_only=true,
        target_socket={address=0x300000,size=0x1000,bind='&apss_router.initiator_socket'},
        load={{bin_file=root..'producer.bin',offset=0}}},
    shared={moduletype='gs_memory',init_mem=true,
        target_socket={address=0x31048000,size=0x5000,bind='&apss_router.initiator_socket'}},
    inputs={moduletype='gs_memory',init_mem=true,
        target_socket={address=0x31050000,size=0x2000,bind='&apss_router.initiator_socket'}},
    shadow={moduletype='gs_memory',init_mem=true,
        target_socket={address=0x3104d000,size=0x2000,bind='&apss_router.initiator_socket'}},
    flash={moduletype='gs_memory',init_mem=true,
        target_socket={address=0x50000000,size=0xc000,bind='&apss_router.initiator_socket'}},
    saved_control0={moduletype='qcom,retained-boot-control-v1',writable_mask=0xffffffff,reset_value=0,
        target_socket={address=0x31b80000,size=4,bind='&apss_router.initiator_socket'}},
    saved_control1={moduletype='qcom,retained-boot-control-v1',writable_mask=0xffffffff,reset_value=0,
        target_socket={address=0x31b80004,size=4,bind='&apss_router.initiator_socket'}},
    primary_period={moduletype='qcom,retained-boot-control-v1',writable_mask=0x1ffff,reset_value=0,
        target_socket={address=0x34a00080,size=4,bind='&apss_router.initiator_socket'}},
    retention={moduletype='qcom,retained-boot-control-v1',writable_mask=0xff,reset_value=0,
        target_socket={address=0x310a92bc,size=4,bind='&apss_router.initiator_socket'}},
    sram_clock={moduletype='qcom,retained-boot-control-v1',writable_mask=0xffffffff,reset_value=0xffffffff,
        target_socket={address=0x310a80bc,size=4,bind='&apss_router.initiator_socket'}},
    trace_control={moduletype='qcom,retained-boot-control-v1',writable_mask=1,reset_value=0,
        target_socket={address=0x31078000,size=4,bind='&apss_router.initiator_socket'}},
    ddr={moduletype='qcom,virtual-ddr-v1',shared_base=0x3104a800,
        dram_base=0x80000000,startup_version_major=0x1d,
        memory_socket={bind='&apss_router.target_socket'}},
    shrm={moduletype='qcom,virtual-shrm-v1',backend_path='ddr',
        target_socket={address=0x31076000,size=0x70,bind='&apss_router.initiator_socket'},
        processor_control_socket={address=0x31079000,size=4,bind='&apss_router.initiator_socket'}},
    second_requester={moduletype='addrtr',mapped_base_addr=0,
        target_socket={address=0x40000000,size=4,relative_addresses=false,
            bind='&apss_router.initiator_socket'},
        initiator_socket={bind='&shrm.processor_control_socket'}},
}
